def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A colored patch is produced by each 2 that lies in, or immediately
    # beside, a region of 3s. Unrelated 2s in the surrounding background
    # are left alone.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            near_three = any(
                0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 3
                for rr in range(r-1, r+2)
                for cc in range(c-1, c+2)
            )
            if near_three:
                for rr in range(max(0, r-1), min(h, r+2)):
                    for cc in range(max(0, c-1), min(w, c+2)):
                        if out[rr][cc] != 2:
                            out[rr][cc] = 1
    return out
